#pragma once
void dominoTargetsTests(Memory initial,std::uintptr_t base,std::uintptr_t game,std::uintptr_t equipment){
    constexpr std::uintptr_t a=0xa00000000,c=a+0x1000,d=a+0x5000,def=a+0x6000,list=a+0x7000,names=a+0x8000,pool=a+0x9000;
    constexpr std::uintptr_t target=a+0xc000,animation=a+0xd000,targetList=a+0xe000,targetDef=a+0xf000,fxOwner=a+0x10000,fxDecl=a+0x11000;
    constexpr std::uintptr_t fxPool=a+0x12000,fxBuckets=a+0x20000,fxNode=a+0x21000;
    constexpr unsigned handle=0x70002,targetHandle=0x80005,ownerHandle=0x90006,mark=37;
    auto m=initial;const auto named=[&](std::uintptr_t decl,std::uintptr_t vt,std::uintptr_t p,const char* text){m.q(decl,base+vt);m.q(decl+8,p);m.str(p,text);};
    m.d(equipment+0xb0,handle);m.q(equipment+0xb8,c);m.q(game+0x3130b0+7*8,a);m.d(a+0xa8,handle);m.d(a+0xac,0x3fff0010);m.q(a,base+0x1c87d58);m.q(a+0x2e8,def);
    named(def,0x1ab58f8,names,"models/powers/phantasmallink/phantasmal_network.def");m.q(a+0x268,list);m.d(a+0x270,1);m.q(list,c);
    m.q(c,base+0x1b62b48);m.q(c+8,d);m.q(c+0x10,a);m.d(c+0x1c,0x2000000a);
    named(d,0x1b62a08,names+0x100,"components/characters/player/base/powers/phantasmallink/phantasmal_network.cpntphantasmalnetwork");
    m.q(c+0x28,list+0x100);m.d(c+0x30,1);m.q(list+0x100,pool);m.q(c+0x68,pool);m.d(c+0x70,16);m.q(d+0x88,fxDecl);
    named(fxDecl,0x1ab3138,names+0x300,kDominoValidatedFx);
    m.d(pool,targetHandle);m.d(pool+8,0x1273);m.q(pool+0x10,animation);m.d(pool+0x90,mark);m.d(pool+0x94,ownerHandle);
    m.q(game+0x3130b0+8*8,target);m.d(target+0xa8,targetHandle);m.q(target,base+0x1c5e108);m.q(target+0x2e8,targetDef);
    named(targetDef,0x1ab58f8,names+0x400,"models/characters/def/generic/dunwall_guard_male_small_01.def");
    m.q(target+0x268,targetList);m.d(target+0x270,1);m.q(targetList,animation);
    m.q(animation,base+0x1b80408);m.q(animation+0x10,target);m.d(animation+0x18,0x1273);m.d(animation+0x1c,0x2000000a);
    float root[3]={1,2,3},pose[12]={1,2,4,1,0,0,0,1,0,0,0,1};m.put(target+0x300,root,12);m.put(pool+0x38,pose,48);
    m.q(game+0x3130b0+9*8,fxOwner);m.d(fxOwner+0xa8,ownerHandle);m.q(fxOwner,base+0x1c887f8);m.d(fxOwner+0xac,0x3fff0010);m.q(fxOwner+0x2e8,0);
    const auto manager=game+0x1f8430,map=manager+0xeef60;m.q(manager,fxPool);m.q(map,fxBuckets);m.d(map+0xc,1);m.d(map+0x10,63);m.q(fxBuckets+(mark&63)*8,fxNode);
    m.d(fxNode,mark);m.d(fxNode+4,0);m.q(fxNode+8,0);m.d(fxPool,ownerHandle);m.d(fxPool+4,mark);m.q(fxPool+8,fxDecl);m.put(fxPool+0x38,pose,48);
    NativeDominoTargets s{};unsigned stage=0;const auto inspect=[&](Memory& x){return readNativeDominoTargets([&](auto a,auto b,auto n){return x.read(a,b,n);},base,s,&stage);};
    const bool valid=inspect(m);if(!valid)std::cerr<<"Domino target fixture stage "<<stage<<'\n';
    require(valid&&s.present&&s.targets.size()==1&&s.targets[0].hasMark&&s.targets[0].key.handle==targetHandle,"Domino reciprocal selected NPC, animation generation and native mark owner");
    const auto known=s.equipment;const auto fast=[&](Memory& x){return readNativeDominoTargets([&](auto a,auto b,auto n){return x.read(a,b,n);},base,s,&stage,&known);};
    require(fast(m)&&s.targets[0].hasMark,"scoped Domino equipment hint still verifies all current target ownership");
    auto cachedBad=m;cachedBad.q(known.player.sword.inventory+0x70,0);cachedBad.d(equipment+0x1c,0);require(fast(cachedBad)&&!s.equipment.equipped&&s.targets[0].hasMark,"native marks can outlive equipment selection without reading sword attachment pose");
    cachedBad=m;cachedBad.q(known.player.sword.inventory+0x10,target);require(!fast(cachedBad),"cached inventory must remain owned by local Emily");
    cachedBad=m;cachedBad.q(known.equipmentDeclaration+0x48,0);require(!fast(cachedBad),"cached inline parent must remain exact");
    cachedBad=m;cachedBad.d(game+0x1f7400,1);require(!fast(cachedBad),"pending gameplay transition retires scoped read");
    cachedBad=m;cachedBad.d(known.entry+0x24,2);require(!fast(cachedBad),"cached entry maximum must retain native identity");
    cachedBad=m;cachedBad.d(known.entity+0xa8,known.handle+0x10000);require(!fast(cachedBad),"cached native equipment generation cannot be recycled");
    cachedBad=m;unsigned cacheReads=0;require(!readNativeDominoTargets([&](auto p,auto d,auto n){const bool ok=cachedBad.read(p,d,n);if(p==known.entry+0x20&&++cacheReads==1)cachedBad.d(p,0);return ok;},base,s,&stage,&known),"quantity transition across scoped frames refused");
    auto bad=m;bad.d(equipment+0xb0,0x3fff0010);require(!inspect(bad),"absent network handle cannot retain foreign component pointer");bad.q(equipment+0xb8,0);require(inspect(bad)&&!s.present,"native uncommitted network is valid absence");
    bad=m;bad.q(c+0x10,target);require(!inspect(bad),"network owner must match equipment-derived entity");
    bad=m;bad.d(a+0xa8,handle+0x10000);require(!inspect(bad),"network entity incarnation cannot be recycled");
    bad=m;bad.q(d,base+0x1b9bd68);require(!inspect(bad),"foreign power declaration refused");
    bad=m;bad.d(a+0x270,2);bad.q(list+8,c);require(!inspect(bad),"duplicate network component refused");
    bad=m;bad.d(c+0x30,5);require(!inspect(bad),"unbounded Domino selection table refused");
    bad=m;bad.q(list+0x100,pool+1);require(!inspect(bad),"node must be aligned in native pool");
    bad=m;bad.q(list+0x100,pool+16*0x150);require(!inspect(bad),"node outside native pool refused");
    bad=m;bad.d(c+0x70,0);require(!inspect(bad),"retired native node pool refused");
    bad=m;bad.d(c+0x30,2);bad.q(list+0x108,pool);require(!inspect(bad),"duplicate selected node refused");
    bad=m;bad.d(pool,1);require(!inspect(bad),"local player cannot impersonate native selected NPC");
    bad=m;bad.d(animation+0x18,0x1274);require(!inspect(bad),"recycled animation generation refused");
    bad=m;bad.q(animation+0x10,a);require(!inspect(bad),"animation component owner mismatch refused");
    bad=m;bad.d(animation+0x1c,0);require(!inspect(bad),"inactive native component reference refused");
    bad=m;bad.d(pool+0x38,0x7fc00000);require(!inspect(bad),"nonfinite native target position refused");
    bad=m;bad.d(pool+0x44,0);require(!inspect(bad),"degenerate target basis refused");
    bad=m;bad.d(pool+0x94,targetHandle);require(!inspect(bad),"mark owner cannot be inferred from target handle");
    bad=m;bad.d(fxOwner+0xa8,ownerHandle+0x10000);require(!inspect(bad),"recycled temporary FX owner refused");
    bad=m;bad.q(fxOwner,base+0x1c87d58);require(!inspect(bad),"generic entity cannot impersonate temporary mark owner");
    bad=m;bad.d(fxPool+4,mark+1);require(!inspect(bad),"recycled mark ID refused");
    bad=m;bad.d(fxPool+0x38,0x447a0000);require(!inspect(bad),"mark displaced far from target refused");
    bad=m;bad.d(pool+0x90,~0u);bad.d(pool+0x94,0x3fff0010);require(inspect(bad)&&s.targets.size()==1&&!s.targets[0].hasMark,"selected node can exist before native mark creation");
    bad=m;unsigned reads=0;require(!readNativeDominoTargets([&](auto p,auto d,auto n){const bool ok=bad.read(p,d,n);if(p==pool+0x90&&++reads==1)bad.d(p,mark+1);return ok;},base,s),"concurrent mark replacement refused");
    bad=m;reads=0;require(!readNativeDominoTargets([&](auto p,auto d,auto n){const bool ok=bad.read(p,d,n);if(p==equipment+0xb0&&++reads==1)bad.d(p,0x3fff0010);return ok;},base,s),"concurrent native network retirement refused");
    dominoLinksTests(m,base,game,known);
    std::cout<<"PASS: Domino selected network, native node pool, animation generation, reciprocal target mark ownership and retirement guards\n";
}
